css=r'''/* V0.19 ALL VIETNAM DESTINATIONS */
.vnHubHero{min-height:78vh;background:#173d34 center/cover no-repeat;color:#fff;position:relative;display:flex;flex-direction:column;justify-content:flex-end;padding:22px 20px 26px}.vnHubHero:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#082e27f5 0%,#082e2780 45%,#082e2715 78%)}.vnHubHero>*{position:relative;z-index:2}.vnHubHero h1{font:800 clamp(48px,13vw,78px)/.9 Georgia,serif;margin:8px 0 13px}.vnHubHero p{font-size:20px;max-width:600px}.vnFacts{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}.vnFacts span{border:1px solid #ffffff80;border-radius:999px;padding:8px 11px;font-weight:800;font-size:12px}.vnExplore{width:100%;border:1px solid #fff;background:#ffffff14;color:#fff;border-radius:999px;font-weight:900;padding:15px}.vnQuick{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:14px}.vnQuick button{border:0;border-radius:14px;background:#fffaf1;color:#14231f;padding:10px 4px;min-height:82px;font-weight:800;font-size:11px}.vnQuick strong{display:block;font-size:23px;margin-bottom:5px}.vnBody{padding:20px 14px 115px}.vnBody h2{font:800 28px/1 Georgia,serif;margin:26px 0 8px}.vnCards{display:grid;grid-template-columns:1fr 1fr;gap:10px}.vnCard{min-height:190px;position:relative;border:0;border-radius:17px;overflow:hidden;background:#173d34 center/cover no-repeat;color:#fff;text-align:left;padding:0}.vnCard:after{content:"";position:absolute;inset:0;background:linear-gradient(0deg,#082e27f2,#082e2710 72%)}.vnCard span{position:absolute;z-index:2;left:12px;right:10px;bottom:11px}.vnCard b{display:block;font-size:17px}.vnCard small{display:block;margin-top:4px}.vnFilters{display:flex;gap:7px;overflow-x:auto;padding:4px 0 12px;position:sticky;top:0;background:#f3ede1e8;backdrop-filter:blur(8px);z-index:10}.vnFilters button{white-space:nowrap;border:1px solid var(--line);background:#fffaf1;border-radius:999px;padding:9px 13px;font-weight:800}.vnFilters button.on{background:var(--deep);color:#fff}.vnResult{display:grid;grid-template-columns:110px 1fr;gap:12px;background:#fffaf1;border:1px solid var(--line);border-radius:17px;padding:10px;margin:10px 0}.vnResultPhoto{min-height:125px;border-radius:13px;background:#173d34 center/cover no-repeat}.vnResult h3{font:800 20px/1.05 "Manrope",sans-serif;margin:5px 0}.vnResult p{font-size:13px;color:var(--muted);margin:5px 0}.vnTags{display:flex;gap:4px;flex-wrap:wrap}.vnTags i{font-style:normal;background:#e8dfcf;border-radius:999px;padding:4px 6px;font-size:9px;font-weight:800}.vnActions{display:flex;gap:6px;margin-top:8px}.vnActions button{border:1px solid var(--line);background:#fff;border-radius:10px;padding:7px;font-weight:800;color:#1768df}.vnFallback{position:relative}.vnFallback:before{content:attr(data-label);position:absolute;inset:0;display:grid;place-items:center;text-align:center;padding:12px;color:#fff;background:linear-gradient(135deg,#173d34,#315d52);font-weight:800}.vnFallback.loaded:before{display:none}@media(max-width:390px){.vnResult{grid-template-columns:95px 1fr}.vnQuick button{font-size:10px}}
'''
s=s.replace('</style>',css+'\n</style>',1)
js=r'''/* V0.19 ALL VIETNAM DESTINATIONS */
DATA.version="0.19";
const VN_FOOD={
"Cái Bè":["hủ tiếu Mỹ Tho","Mekong fruit","coconut sweets"],"Sa Đéc":["hủ tiếu Sa Đéc","lotus dishes","Mekong coffee"],"Cần Thơ":["bánh cống","bánh xèo","Cái Răng breakfast"],"Long Xuyên":["bún cá Long Xuyên","cơm tấm","Mekong market snacks"],"Châu Đốc":["bún cá Châu Đốc","mắm Châu Đốc","tung lò mò"],"Đà Lạt":["bánh căn","bánh tráng nướng","Đà Lạt coffee"],"Đắk Lắk":["Buôn Ma Thuột coffee","cơm lam","Central Highlands grilled chicken"],"Pleiku":["phở khô Gia Lai","cơm lam","Highlands coffee"],"Kon Tum":["gỏi lá","cơm lam","Highlands coffee"],"Măng Đen":["grilled chicken cơm lam","forest vegetables","local coffee"],"Quy Nhơn":["bánh xèo tôm nhảy","bún chả cá","seafood"],"Phú Yên":["mắt cá ngừ đại dương","bánh canh hẹ","seafood"],"Nha Trang":["bún chả cá","nem nướng","seafood"],"Hội An":["cao lầu","cơm gà Hội An","white rose dumplings"],"Đà Nẵng":["mì Quảng","bún chả cá","bánh tráng cuốn thịt heo"],"Huế":["bún bò Huế","cơm hến","bánh bèo / nậm / lọc"],"Phong Nha / Quảng Bình":["cháo canh","bánh bột lọc","local farm food"],"Ninh Bình":["cơm cháy","goat dishes","mountain snails"],"Hà Nội":["bún chả","phở","egg coffee"],"Cao Bằng":["bánh cuốn Cao Bằng","vịt quay","hạt dẻ Trùng Khánh"],"Hà Giang Loop":["thắng cố","cháo ấu tẩu","buckwheat cake"],"Sa Pa":["salmon hotpot","thắng cố","grilled street food"]};
function vnSlug(x){return x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function vnStop(){const x=cur();return x&&x.c.id==='vietnam'?x:null}
function vnBaseItems(x){let parts=(x.d.summary||'').split(';').map(v=>v.trim()).filter(Boolean);let food=VN_FOOD[x.d.name]||[];let items=[];parts.forEach((v,i)=>items.push({id:'core-'+i,title:v,summary:`Experience ${v} in and around ${x.d.name}.`,tags:[i<2?'Must Do':'Local Life',/food|coffee|market|seafood|dish/i.test(v)?'Food':'Culture']}));food.forEach((v,i)=>items.push({id:'food-'+i,title:v,summary:`Try ${v} where it belongs, with a local or market setting where possible.`,tags:['Food','Local Life']}));let generics=[['Local market at its busiest','Go early and use the market as a window into everyday life.',['Local Life','Markets']],['Neighbourhood wander','Leave the headline sights and walk a lived-in local area.',['Unique','Local Life']],['Sunrise or golden-hour viewpoint','See the landscape at its most atmospheric.',['Must Do','Views']],['Local coffee stop','Slow down at a locally distinctive café or coffee producer.',['Food','Coffee']],['Signature day trip','Use this base to reach the strongest nearby landscape or cultural experience.',['Day Trip','Must Do']]];generics.forEach((g,i)=>items.push({id:'local-'+i,title:g[0],summary:g[1],tags:g[2]}));return items}
const vnImgCache={};async function vnImg(q){if(vnImgCache[q]!==undefined)return vnImgCache[q];try{let u='https://en.wikipedia.org/w/api.php?action=query&generator=search&gsrsearch='+encodeURIComponent(q+' Vietnam')+'&gsrlimit=1&prop=pageimages&piprop=original|thumbnail&pithumbsize=900&format=json&origin=*';let j=await (await fetch(u)).json();let pg=Object.values(j.query?.pages||{})[0];return vnImgCache[q]=pg?.original?.source||pg?.thumbnail?.source||''}catch(e){return vnImgCache[q]=''}}
function hydrateVN(){document.querySelectorAll('[data-vnimg]').forEach(async el=>{let u=await vnImg(el.dataset.vnimg);if(u){el.style.backgroundImage=`url("${u}")`;el.classList.add('loaded')}})}
function vnSavedKey(x,it){return 'vn-'+vnSlug(x.d.name)+'-'+it.id}function vnSaved(x,it){return !!state.saved[vnSavedKey(x,it)]}
function vnHub(){let x=vnStop();if(!x)return home();if(/ho chi minh|hcmc|sai gon|saigon/i.test(x.d.name)){hcmOverviewV15();return}nav.hidden=true;nav.style.display='none';let items=vnBaseItems(x),done=items.filter(it=>state.done[vnSavedKey(x,it)]).length,saved=items.filter(it=>vnSaved(x,it)).length,pct=Math.round(done/items.length*100),next=DATA.countries.find(c=>c.id==='vietnam').destinations[x.di+1];let hero=x.d.name;app.innerHTML=`<div><section class="vnHubHero vnFallback" data-vnimg="${hero}" data-label="${hero}"><button class="circleBtn" id="vnBack" style="position:absolute;top:18px;left:16px">‹</button><div class="eyebrow">🇻🇳 VIETNAM · CURRENT CHAPTER</div><h1>${x.d.name}</h1><p>${x.d.summary}</p><div class="vnFacts"><span>${items.length} EXPERIENCES</span><span>${x.d.days} DAYS</span><span>${x.d.tier} PRIORITY</span></div><button class="vnExplore" id="vnExplore">Explore Experiences →</button><div class="vnQuick"><button data-vnf="Must Do"><strong>★</strong>Must Do</button><button data-vnf="Food"><strong>♨</strong>Food & Drink</button><button data-vnf="Day Trip"><strong>▰</strong>Day Trips</button><button data-vnf="Unique"><strong>◇</strong>Hidden Gems</button></div></section><section class="vnBody"><h2>Trip Progress</h2><div class="hubProgress"><div class="hubProgressTop"><span>${done} / ${items.length} completed</span><span>${pct}%</span></div><div class="progress"><i style="width:${pct}%"></i></div></div><h2>Don't Miss</h2><div class="vnCards">${items.filter(it=>it.tags.includes('Must Do')).slice(0,4).map(it=>`<button class="vnCard vnFallback" data-vnimg="${it.title} ${x.d.name}" data-label="${it.title}" data-vnopen="${it.id}"><span><b>${it.title}</b><small>${it.summary}</small></span></button>`).join('')}</div><h2>My Journey</h2><div class="hubJourney"><button id="vnSaved">♡<br>${saved} Saved</button><button id="vnDone">✓<br>${done} Done</button><button id="vnFood">♨<br>Food & Drink</button></div>${next?`<h2>Go Next</h2><button class="hubNext vnFallback" data-vnimg="${next.name}" data-label="${next.name}" id="vnNext"><span><small>NEXT DESTINATION</small><b>${next.name} →</b><small>${next.summary}</small></span></button>`:''}</section>${hcmBottom('overview')}</div>`;vnBack.onclick=()=>destinationSelector('vietnam');vnExplore.onclick=()=>vnExperiences('All');document.querySelectorAll('[data-vnf]').forEach(b=>b.onclick=()=>vnExperiences(b.dataset.vnf));vnSaved.onclick=()=>vnExperiences('Saved');vnDone.onclick=()=>vnExperiences('Completed');vnFood.onclick=()=>vnExperiences('Food');if(next)vnNext.onclick=()=>{state.here='Vietnam · '+next.name;save();vnHub()};wireV15();hydrateVN()}
function vnExperiences(filter='All'){let x=vnStop(),items=vnBaseItems(x);if(filter==='Saved')items=items.filter(it=>vnSaved(x,it));else if(filter==='Completed')items=items.filter(it=>state.done[vnSavedKey(x,it)]);else if(filter!=='All')items=items.filter(it=>it.tags.includes(filter));nav.hidden=true;nav.style.display='none';let filters=['All','Must Do','Unique','Food','Culture','Local Life','Day Trip','Saved'];app.innerHTML=`<div class="vnBody"><button class="back" id="vxBack">← ${x.d.name}</button><div class="vnFilters">${filters.map(f=>`<button class="${f===filter?'on':''}" data-vxfilter="${f}">${f}</button>`).join('')}</div><h1 style="font:800 42px Georgia,serif;margin:15px 0 2px">${filter==='All'?'Explore '+x.d.name:filter}</h1><p>${items.length} matching experiences</p>${items.map(it=>`<article class="vnResult"><div class="vnResultPhoto vnFallback" data-vnimg="${it.title} ${x.d.name}" data-label="${it.title}"></div><div><div class="vnTags">${it.tags.map(t=>`<i>${t}</i>`).join('')}</div><h3>${it.title}</h3><p>${it.summary}</p><div class="vnActions"><button data-vnsave="${it.id}">${vnSaved(x,it)?'♥ Saved':'♡ Save'}</button><button data-vndone="${it.id}">${state.done[vnSavedKey(x,it)]?'✓ Done':'Mark done'}</button></div></div></article>`).join('')}${hcmBottom('experiences')}</div>`;vxBack.onclick=vnHub;document.querySelectorAll('[data-vxfilter]').forEach(b=>b.onclick=()=>vnExperiences(b.dataset.vxfilter));document.querySelectorAll('[data-vnsave]').forEach(b=>b.onclick=()=>{let it=vnBaseItems(x).find(z=>z.id===b.dataset.vnsave),k=vnSavedKey(x,it);state.saved[k]=!state.saved[k];save();vnExperiences(filter)});document.querySelectorAll('[data-vndone]').forEach(b=>b.onclick=()=>{let it=vnBaseItems(x).find(z=>z.id===b.dataset.vndone),k=vnSavedKey(x,it);state.done[k]=!state.done[k];save();vnExperiences(filter)});wireV15();hydrateVN()}
const _home019=home;home=function(){let x=cur();if(x&&x.c.id==='vietnam'){vnHub();return}_home019()};
const _do019=doHere;doHere=function(){let x=cur();if(x&&x.c.id==='vietnam'){if(/ho chi minh|hcmc|sai gon|saigon/i.test(x.d.name))hcmExperiencesV15('All');else vnExperiences('All');return}_do019()};
'''
needle='document.querySelectorAll("nav button").forEach'
s=s.replace(needle,js+'\n'+needle,1)
p.write_text(s,encoding='utf-8');print('V0.19 applied')
